window.PAIRS=[{"n":4,"s":0.774,"o":{"i":"관세사2019_36-34-3","t":"원료를 공급받거나 위탁 공임만을 받고 제조한 물품을 제조장에서 위탁자의 제품 저장창고에 반출하는 것","y":2019,"e":"관세사 1차"},"x":{"i":"관세사2020_37-33-3","t":"원료를 공급받거나 위탁 공임만을 받고 제조한 물품을 제조장에서 위탁자의 제품 저장 창고에 반출하는 것은 개별소비세를 징수한다.","y":2020,"e":"관세사 1차"}},{"n":4,"s":0.651,"o":{"i":"관세사2018_35-35-5","t":"미납세반출자와 그 반출된 물품을 반입한 자가 동일한 사업자인 경우에는 해당 물품을 반입지에서 판매 또는 반출할 때 미납세반출자가 대통령령으로 정하는 바에 따라 해당 물품에 대한 개별소비세를 관할 세무서장 또는 세관장에게 신고 ㆍ납부할 수 있다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2017_34-05-3","t":"미납세반출자와 그 반출된 물품을 반입한 자가 동일한 사업자가 아닌 경우에도 해당 물품을 반입지에서 판매 또는 반출할 때 미납세반출자가 해당 물품에 대한 개별소비세를 관할 세무서장 또는 세관장에게 신고·납부할 수 있다.","y":2017,"e":"관세사 1차"}},{"n":4,"s":0.65,"o":{"i":"관세사2019_36-32-4","t":"반출되는 물품의 운송비를 그 운송거리나 운송방법에 상관없이 같은 금액으로 하여 그 반출가격에 포함시키거나 그 금액을 별도로 받는 경우(운송기관이 운송을 담당하는 경우를 포함한다)에는 그 운송비를 포함한 가격에 상당하는 금액으로 한다.","y":2019,"e":"관세사 1차"},"x":{"i":"관세사2017_34-04-4","t":"반출되는 물품의 운송비를 그 운송거리나 운송방법에 상관없이 같은 금액으로 하여 그 반출가격에 포함시키거나 그 금액을 별도로 받는 경우에는 그 운송비를 제외한 가격에 상당하는 금액으로 계산한다.","y":2017,"e":"관세사 1차"}},{"n":4,"s":0.633,"o":{"i":"관세사2023_40-34-4","t":"과세물품이 제조장에 있다가 파산절차로 환가(換價)되는 경우에는 제조장에서 반출하는 것으로 본다.","y":2023,"e":"관세사 1차"},"x":{"i":"관세사2026_43-35-1","t":"과세물품이 제조장에 있다가 파산절차로 환가되는 경우에는 제조장에서 반출하는 것으로 보지 아니한다.","y":2026,"e":"관세사 1차"}},{"n":5,"s":0.75,"o":{"i":"관세사2026_43-38-1","t":"주류 제조장에서 반출하는 경우 탁주에 대한 주세의 과세표준은 반출한 수량으로 한다.","y":2026,"e":"관세사 1차"},"x":{"i":"관세사2026_43-38-3","t":"주류 제조장에서 반출하는 경우 증류주류에 대한 주세의 과세표준은 반출한 수량으로 한다.","y":2026,"e":"관세사 1차"}},{"n":5,"s":0.672,"o":{"i":"관세사2019_36-37-1","t":"주류 제조장에서 주류를 출고한 자는 매 분기 주류 제조장에서 출고한 주류의 종류, 알코올분, 수량, 가격, 세율, 산출세액, 공제세액, 환급세액, 납부세액 등을 적은 신고서를 출고한 날이 속하는 분기의 다음 달 25일까지 관할 세무서장에게 제출하여야 한다.","y":2019,"e":"관세사 1차"},"x":{"i":"관세사2023_40-39-1","t":"주류 제조장에서 주류를 반출한 자는 매 월 주류 제조장에서 반출한 주류의 종류, 알코올분, 수량, 가격, 세율, 산출세액, 공제세액, 환급세액, 납부세액 등을 적은 신고서를 반출한 날이 속하는 달의 다음 달 20일까지 관할 세무서장에게 제출하여야 한다.","y":2023,"e":"관세사 1차"}},{"n":5,"s":0.648,"o":{"i":"관세사2020_37-40-5","t":"주류를 제조장에서 마신 경우에는 출고된 것으로 보는 날이 속하는 월 또는 그 전월의 당해주류와 동일한 규격과 용량에 대한 통상가격을 주류의 가격으로 한다. 회계 학 ※ 아래 문제들에서 특별한 언급이 없는 한, 기업의 보고기간(회계기간)은 매년 1월 1일부터 12월 31일까지이다. 또한 기업은 주권상장법인으로 계속해서 한국채택 국제회계기준(K-IFRS)을 적용해오고 있다고 가정하고, 보기 중에서 물음에 가장 합당한 답을 고르시오. 단, 자료에서 제시한 모든 항목과 금액은 중요하며, 자료에서 제시한 것 외의 사항은 고려하지 않고 답한다. 예를 들어 법인세에 대하여 언급이 없으면 법인세효과는 고려하지 않는다.","y":2020,"e":"관세사 1차"},"x":{"i":"관세사2022_39-40-5","t":"무상으로 반출하는 경우로서 통상가격을 산출할 수 없는 때에는 제조원가(회계학상 개념에 의한 제조원가)에 10 % 상당 이윤을 가산한 가격으로 한다. 회계 학 ※ 아래 문제들에서 특별한 언급이 없는 한, 기업의 보고기간(회계기간)은 매년 1월 1일부터 12월 31일까지이다. 또한 기업은 주권상장법인으로 계속해서 한국채택 국제회계기준(K-IFRS)을 적용해오고 있다고 가정하고, 보기 중에서 물음에 가장 합당한 답을 고르시오. 단, 자료에서 제시한 모든 항목과 금액은 중요하며, 자료에서 제시한 것 외의 사항은 고려하지 않고 답한다. 예를 들어 법인세에 대하여 언급이 없으면 법인세효과는 고려하지 않는다.","y":2022,"e":"관세사 1차"}},{"n":5,"s":0.579,"o":{"i":"관세사2024_41-40-5","t":"주류 제조자는 관할 세무서장이 보존을 명한 납세보증주류를 처분하거나 제조장에서 반출할 수 없다. 회계 학 ※ 아래 문제들에서 특별한 언급이 없는 한, 기업의 보고기간(회계기간)은 매년 1월 1일부터 12월 31일까지이다. 또한 기업은 주권상장법인으로 계속해서 한국채택 국제회계기준(K-IFRS)을 적용해오고 있다고 가정한다. 단, 자료에서 제시한 모든 항목과 금액은 중요하며, 자료에서 제시한 것 외의 사항은 고려하지 않고 답한다. 예를 들어 법인세에 대하여 언급이 없으면 법인세효과는 고려하지 않는다.","y":2024,"e":"관세사 1차"},"x":{"i":"관세사2023_40-40-5","t":"「주세법」 제21조에 따라 관할 세무서장은 주세 보존을 위하여 필요하다고 인정하는 경우에는 주류 제조자에 대해 납세 보증으로 보존해야 하는 주류의 가격을 정하여 명할 수 있으나 그 주류의 보존기간은 정하여 명할 수 없다. 회계 학 ※ 아래 문제들에서 특별한 언급이 없는 한, 기업의 보고기간(회계기간)은 매년 1월 1일부터 12월 31일까지이다. 또한 기업은 주권상장법인으로 계속해서 한국채택 국제회계기준(K-IFRS)을 적용해오고 있다고 가정하고, 답지항 중에서 물음에 가장 합당한 답을 고르시오. 단, 자료에서 제시한 모든 항목과 금액은 중요하며, 자료에서 제시한 것 외의 사항은 고려하지 않고 답한다. 예를 들어 법인세에 대하여 언급이 없으면 법인세효과는 고려하지 않는다.","y":2023,"e":"관세사 1차"}},{"n":2,"s":0.849,"o":{"i":"관세사2024_41-07-2","t":"외국으로부터 국내에 도착한 물품으로서 수입신고가 수리되기 전의 것을 국내에 반입하는 것은 재화의 수입에 해당한다.","y":2024,"e":"관세사 1차"},"x":{"i":"관세사2025_42-03-3","t":"외국으로부터 국내에 도착한 물품으로서 수입신고가 수리되기 전의 것을 국내에 반입하는 것은 재화의 수입에 해당하지 아니한다.","y":2025,"e":"관세사 1차"}},{"n":2,"s":0.833,"o":{"i":"관세사2024_41-14-2","t":"면세의 포기를 신고한 사업자는 신고한 날부터 3년간 부가가치세를 면제받지 못한다.","y":2024,"e":"관세사 1차"},"x":{"i":"관세사2023_40-14-4","t":"면세의 포기를 신고한 사업자는 신고한 날부터 5년간 부가가치세를 면제받지 못한다.","y":2023,"e":"관세사 1차"}},{"n":2,"s":0.736,"o":{"i":"관세사2017_34-22-5","t":"수출신고가 수리된 물품으로서 선적되지 아니한 물품을 보세구역에서 반입하는 경우는 재화의 수입에 해당하지 않는다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2025_42-03-1","t":"수출신고가 수리된 물품으로서 선적되지 아니한 물품을 보세구역에서 반입하는 경우 재화의 수입에 해당한다.","y":2025,"e":"관세사 1차"}},{"n":2,"s":0.606,"o":{"i":"관세사2025_42-05-3","t":"고용관계에 따라 근로를 제공하는 것은 용역의 공급으로 보지 아니한다.","y":2025,"e":"관세사 1차"},"x":{"i":"관세사2020_37-06-1","t":"고용관계에 따라 근로를 제공하는 것은 용역의 공급에 해당한다.","y":2020,"e":"관세사 1차"}},{"n":3,"s":0.733,"o":{"i":"관세사2018_35-15-2","t":"대손세액공제를 받은 사업자가 대손금액의 전부 또는 일부를 회수한 경우에는 회수한 대손금액에 관련된 대손세액을 회수한 날이 속하는 과세기간의 매출세액에 더한다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2017_34-20-4","t":"대손세액공제를 받은 사업자가 대손금액의 전부 또는 일부를 회수한 경우에는 회수한 대손금액에 관련된 대손세액을 공급일이 속하는 과세기간의 매출세액에 더하여 수정신고 한다.","y":2017,"e":"관세사 1차"}},{"n":3,"s":0.72,"o":{"i":"관세사2017_34-32-4","t":"세금계산서의 필요적 기재사항의 일부가 착오 또는 과실로 적혀 있지 아니하거나 사실과 다른 경우(해당 세금계산서에 적힌 나머지 필요적 기재사항 또는 임의적 기재사항으로 보아 거래사실이 확인되는 경우 제외)의 가산세는 그 공급가액의 1퍼센트에 해당하는 금액으로 한다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2019_36-23-2","t":"발급한 세금계산서의 필요적 기재사항의 전부 또는 일부가 착오 또는 과실로 적혀 있지 아니하거나 사실과 다른 경우(해당 세금계산서에 적힌 나머지 필요적 기재사항 또는 임의적 기재사항으로 보아 거래사실이 확인되는 경우에는 제외한다)의 가산세는 그 공급가액의 0.5 %에 해당하는 금액으로 한다.","y":2019,"e":"관세사 1차"}},{"n":3,"s":0.686,"o":{"i":"관세사2017_34-18-2","t":"법인사업자와 직전 연도의 사업장별 재화 및 용역의 공급가액 합계액이 3억원 이상인 개인사업자는 전자세금계산서를 발급하여야 한다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2019_36-28-1","t":"법인사업자와 직전 연도의 사업장별 재화 및 용역의 공급가액(면세공급가액을 제외한다)의 합계액이 2억원 이상인 개인사업자는 전자세금계산서를 발급하여야 한다.","y":2019,"e":"관세사 1차"}},{"n":3,"s":0.635,"o":{"i":"관세사2018_35-13-3","t":"관계 증명서류 등에 따라 실제거래사실이 확인되는 경우로서 해당 거래일을 작성 연월일로 하여 세금계산서를 발급하는 경우에는 재화 또는 용역의 공급일이 속하는 달의 다음 달 10일(그 날이 공휴일 또는 토요일인 경우 바로 다음 영업일)까지 세금계산서를 발급할 수 있다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2019_36-28-3","t":"관계 증명서류 등에 따라 실제거래사실이 확인되는 경우로서 해당 거래일이 속하는 달의 말일을 작성 연월일로 하여 세금계산서를 발급하는 경우에는 재화 또는 용역의 공급일이 속하는 달의 다음 달 10일까지 세금계산서를 발급하여야 한다.","y":2019,"e":"관세사 1차"}},{"n":1,"s":0.814,"o":{"i":"관세사2019_36-06-2","t":"사업장 단위로 등록한 사업자가 사업자 단위 과세 사업자로 변경하려면 사업자 단위 과세 사업자로 적용받으려는 과세기간 개시 20일 전까지 사업자의 본점 또는 주사무소 관할 세무서장에게 변경등록을 신청하여야 한다.","y":2019,"e":"관세사 1차"},"x":{"i":"관세사2026_43-02-5","t":"사업장단위로 등록한 사업자가 사업자 단위 과세 사업자로 변경하려면 사업자 단위 과세 사업자로 적용받으려는 과세기간 개시 전까지 사업자의 본점 또는 주사무소 관할 세무서장에게 변경등록을 신청하여 허가를 받아야 한다.","y":2026,"e":"관세사 1차"}},{"n":1,"s":0.786,"o":{"i":"관세사2025_42-02-3","t":"박람회 등 행사가 개최되는 장소에 개설한 임시사업장으로서 대통령령으로 정하는 바에 따라 신고된 장소는 사업장으로 보지 아니한다.","y":2025,"e":"관세사 1차"},"x":{"i":"관세사2024_41-04-3","t":"각종 박람회 등 행사가 개최되는 장소에 개설한 임시사업장으로서 대통령령으로 정하는 바에 따라 신고된 장소는 사업장으로 본다.","y":2024,"e":"관세사 1차"}},{"n":1,"s":0.785,"o":{"i":"관세사2018_35-04-3","t":"사업장 관할 세무서장은 사업자등록의 신청 내용을 보정(補正)할 필요가 있다고 인정될 때에는 10일 이내의 기간을 정하여 보정을 요구할 수 있다.","y":2018,"e":"관세사 1차"},"x":{"i":"관세사2017_34-24-5","t":"사업장 관할 세무서장은 사업자등록의 신청 내용을 보정할 필요가 있다고 인정될 때에는 20일 이내의 기간을 정하여 보정을 요구할 수 있다.","y":2017,"e":"관세사 1차"}},{"n":1,"s":0.608,"o":{"i":"관세사2017_34-25-2","t":"사업장 외의 장소도 사업자의 신청에 따라 추가로 사업장으로 등록할 수 있으나, 무인자동판매기를 통하여 재화ㆍ용역을 공급하는 사업의 경우에는 그러하지 아니하다.","y":2017,"e":"관세사 1차"},"x":{"i":"관세사2025_42-02-5","t":"무인자동판매기를 통하여 재화를 공급하는 사업의 경우 사업장 외의 장소도 사업자의 신청에 따라 추가로 사업장으로 등록할 수 있다.","y":2025,"e":"관세사 1차"}}];
